#ifndef KICH_R4_MATERIAL_LUT_H
#define KICH_R4_MATERIAL_LUT_H
/* P0-L3: SoC r2_rendertarget.cpp s_material, generated by the same float code.
 * R2 uses a 128x256x4 A8L8 volume (x=dot(L,N), y=dot(H,N), z=material slice).
 * R4 stores the four slices stacked in one RGBA8 2D texture, rows slice*256+y:
 * R=G=B=diffuse (L), A=specular. The shader reproduces tex3D addressing. */
#include <stdint.h>
#include <math.h>
#include <vector>
namespace kich_r4_material_lut {
enum {LdotN=128,LdotH=256,Slices=4,Width=LdotN,Height=LdotH*Slices};
inline int32_t Quantize(float v){const int32_t q=static_cast<int32_t>(floorf(v*255.5f));return q<0?0:q>255?255:q;}
inline void Texel(unsigned slice,unsigned x,unsigned y,unsigned char& diffuse,unsigned char& specular){
    const float ld=float(x)/float(LdotN-1);
    float ls=float(y)/float(LdotH-1)+.0000001f; // EPS_S
    ls*=powf(ld,1/32.f);
    float fd,fs;
    switch(slice){
    case 0:fd=powf(ld,.75f);fs=powf(ls,16.f)*.5f;break;           // looks like OrenNayar
    case 1:fd=powf(ld,.90f);fs=powf(ls,24.f);break;               // looks like Blinn
    case 2:fd=ld;fs=powf(ls*1.01f,128.f);break;                   // looks like Phong
    case 3:{const float s0=fabsf(1-fabsf(.05f*sinf(33.f*ld)+ld-ls)); // looks like Metal
        const float s1=fabsf(1-fabsf(.05f*cosf(33.f*ld*ls)+ld-ls));
        const float s2=fabsf(1-fabsf(ld-ls));
        fd=ld;fs=powf(s0>s1?(s0>s2?s0:s2):(s1>s2?s1:s2),24.f);fs*=powf(ld,1/7.f);}break;
    default:fd=fs=0;
    }
    int32_t d=Quantize(fd),s=Quantize(fs);
    if(y==LdotH-1 && x==LdotN-1)d=s=255;
    diffuse=static_cast<unsigned char>(d);specular=static_cast<unsigned char>(s);
}
// Lighting draws bind the table at t10/s11 (terrain_lmap is geometry-only).
// R2 r_Sampler_clw: LINEAR min/mag, no mips; the shader clamps U/V to texel
// centres within a slice and wraps W itself, so this state cannot bleed slices.
enum {Slot=10};
template<class Draw,class Handle> inline void Bind(Draw& draw,Handle table){
    draw.textures[Slot]=table;
    draw.extra_samplers[Slot-8].u=draw.extra_samplers[Slot-8].v=draw.extra_samplers[Slot-8].w=3; // clamp
    draw.extra_samplers[Slot-8].min_filter=draw.extra_samplers[Slot-8].mag_filter=2;          // linear
    draw.extra_samplers[Slot-8].mip_filter=0;draw.extra_samplers[Slot-8].anisotropy=1;
    draw.extra_samplers[Slot-8].border=draw.extra_samplers[Slot-8].lod_bias_bits=draw.extra_samplers[Slot-8].max_mip=0;
}
inline void Put32(std::vector<unsigned char>& d,unsigned offset,uint32_t value){for(unsigned i=0;i<4;++i)d[offset+i]=static_cast<unsigned char>(value>>(i*8));}
// Uncompressed RGBA8 DDS, one mip, accepted by kich_r4_dds::Parse.
inline std::vector<unsigned char> Dds(){
    std::vector<unsigned char> d(128+Width*Height*4,0);
    Put32(d,0,0x20534444);Put32(d,4,124);Put32(d,8,0x100f);Put32(d,12,Height);Put32(d,16,Width);Put32(d,20,Width*4);
    Put32(d,76,32);Put32(d,80,0x41);Put32(d,88,32);Put32(d,92,0xff);Put32(d,96,0xff00);Put32(d,100,0xff0000);Put32(d,104,0xff000000);Put32(d,108,0x1000);
    for(unsigned slice=0;slice<Slices;++slice)for(unsigned y=0;y<LdotH;++y)for(unsigned x=0;x<LdotN;++x){
        unsigned char diffuse,specular;Texel(slice,x,y,diffuse,specular);
        const unsigned at=128+((slice*LdotH+y)*Width+x)*4;d[at]=d[at+1]=d[at+2]=diffuse;d[at+3]=specular;}
    return d;
}
}
#endif
